 private text(s:string,x:number,y:number,size=22,color='#def1fa',align:CanvasTextAlign='left',weight=500){const c=this.ctx;c.font=`${weight} ${size}px system-ui,"Microsoft YaHei",sans-serif`;c.fillStyle=color;c.textAlign=align;c.textBaseline='middle';c.fillText(s,x,y);}
